//! Static tables generated by build.rs from data/*.json (see
//! data/README.md for their sources and licenses).

/// A deinflection condition (part of speech or inflected form).
#[derive(Debug)]
pub struct ConditionData {
    /// Identifier used in rules and in dictionaries' `rules` field.
    pub id: &'static str,
    /// Whether dictionary entries can carry this condition.
    pub is_dictionary_form: bool,
    /// Bit flags (several bits for conditions with sub-conditions).
    pub flags: u32,
}

/// A named group of deinflection rules (e.g. "-te", "potential").
#[derive(Debug)]
pub struct TransformData {
    pub id: &'static str,
    pub name: &'static str,
    pub description: Option<&'static str>,
    pub rules: &'static [RuleData],
}

/// One rule: replace the inflected suffix (or the whole word) with the
/// deinflected text, when the current conditions allow it.
#[derive(Debug)]
pub struct RuleData {
    /// Whole-word rule (text must equal `inflected`) instead of a suffix.
    pub whole_word: bool,
    pub inflected: &'static str,
    pub deinflected: &'static str,
    pub conditions_in: u32,
    pub conditions_out: u32,
}

include!(concat!(env!("OUT_DIR"), "/ja_data.rs"));
